// Package.swift — migrate one target at a time, leaves first.
let package = Package(
  name: "App",
  targets: [
    // Done: this leaf is clean, so it opts into the language mode outright.
    .target(
      name: "CoreModels",
      swiftSettings: [.swiftLanguageMode(.v6)]
    ),

    // In progress: still Swift 5, so every violation is a warning and the
    // target keeps building while the team burns the list down.
    .target(
      name: "Networking",
      dependencies: ["CoreModels"],
      swiftSettings: [
        .swiftLanguageMode(.v5),
        .enableUpcomingFeature("StrictConcurrency"),        // == -strict-concurrency=complete
        .enableUpcomingFeature("GlobalConcurrency"),        // SE-0412: global and static var
        .enableUpcomingFeature("InferSendableFromCaptures"),
      ]
    ),

    // Not started: `targeted` only checks code that already uses async/await,
    // which is the cheap first pass on a large legacy target.
    .target(
      name: "LegacyUI",
      dependencies: ["Networking"],
      swiftSettings: [
        .swiftLanguageMode(.v5),
        .unsafeFlags(["-strict-concurrency=targeted"]),     // fine in an app package
      ]
    ),
  ]
)

// The same staging in an Xcode target's build settings:
//
//   SWIFT_STRICT_CONCURRENCY               = complete
//   SWIFT_UPCOMING_FEATURE_GLOBAL_CONCURRENCY = YES
//   SWIFT_VERSION                          = 5      // flip to 6 last, per target
//
// A separate, later decision — it makes migration easier but changes semantics:
//   SWIFT_APPROACHABLE_CONCURRENCY         = YES
//   SWIFT_DEFAULT_ACTOR_ISOLATION          = MainActor

import Foundation
import Synchronization

// HONEST 1 — the lock is declared next to the storage and nothing bypasses it.
enum Metrics {
  private static let lock = NSLock()
  // Invariant: only read or written while `lock` is held. That sentence is the
  // entire justification for the annotation below.
  nonisolated(unsafe) private static var counts: [String: Int] = [:]

  static func bump(_ key: String) {
    lock.lock(); defer { lock.unlock() }
    counts[key, default: 0] += 1
  }
}

// HONEST 2 — assigned once during launch, before any Task exists; read-only after.
enum Environment {
  nonisolated(unsafe) static var container: Container!
}
// application(_:didFinishLaunchingWithOptions:):
//   Environment.container = Container.live

// HONEST 3 — interop. Thread safety is documented on the C side; the compiler
// has no way to see it either way.
nonisolated(unsafe) let engine = legacy_engine_create()

// SILENCER — compiles, races on the first concurrent write. The annotation
// covers the declaration, never the dictionary the value points at.
// nonisolated(unsafe) var imageCache: [URL: Data] = [:]

// The fix the compiler keeps re-checking for you: the value is unreachable
// without taking the lock, so nothing is being promised on trust.
let imageCache = Mutex<[URL: Data]>([:])

func store(_ data: Data, for url: URL) {
  imageCache.withLock { $0[url] = data }
}

func cached(_ url: URL) -> Data? {
  imageCache.withLock { $0[url] }
}

import Foundation
import Synchronization

// Rejected, one reason each:
// class NotFinal: Sendable { let a = 1 }
//   -> non-final class 'NotFinal' cannot conform to the 'Sendable' protocol
// final class HasVar: Sendable { var a = 1 }
//   -> stored property 'a' of 'Sendable'-conforming class 'HasVar' is mutable
// final class BadProp: Sendable { let s: NSMutableString = "" }
//   -> stored property 's' has non-Sendable type 'NSMutableString'
// final class Sub: MyBase, Sendable { }
//   -> 'Sendable' class 'Sub' cannot inherit from another class other than 'NSObject'

// All four boxes ticked. Note the conformance is written out: a class never
// infers it, however immutable it looks.
final class Config: Sendable {
  let apiKey: String
  let logoName: String        // carry a name; resolve the image on the main actor
  init(apiKey: String, logoName: String) {
    self.apiKey = apiKey
    self.logoName = logoName
  }
}

// NSObject is the one permitted superclass.
final class Token: NSObject, Sendable {
  let raw: String
  init(raw: String) { self.raw = raw; super.init() }
}

// @unchecked: the compiler checks nothing here, so the comment is the contract.
final class Session: @unchecked Sendable {
  private let lock = NSLock()
  private var cookies: [String] = []   // invariant: only touched under `lock`

  var all: [String] { lock.lock(); defer { lock.unlock() }; return cookies }
  func add(_ c: String) { lock.lock(); defer { lock.unlock() }; cookies.append(c) }
}

// Same behaviour, but checked: Mutex is Sendable, so this conformance is real
// and survives whoever adds a property next year.
final class SafeSession: Sendable {
  private let cookies = Mutex<[String]>([])

  var all: [String] { cookies.withLock { $0 } }
  func add(_ c: String) { cookies.withLock { $0.append(c) } }
}

import Synchronization

// error: static property 'current' is not concurrency-safe because it is
//        nonisolated global shared mutable state
// enum Session { static var current: User? }

// 1. Immutable — and the type it holds is Sendable too, which is the half
//    people forget. Actors are Sendable by definition.
actor ImageCache {
  private var storage: [URL: Data] = [:]
  func data(for url: URL) -> Data? { storage[url] }
  func store(_ d: Data, for url: URL) { storage[url] = d }
}
enum Services { static let cache = ImageCache() }

// Still an error: `let` fixed the mutation, not the type.
// final class Analytics { var queue: [String] = [] }
// enum Services2 { static let analytics = Analytics() }
//   -> ... because non-'Sendable' type 'Analytics' may have shared mutable state

// 2. Isolate it — reads from elsewhere become awaits, which is the point.
@MainActor
enum Session {
  static var current: User?
}

func greeting() async -> String {
  await Session.current?.name ?? "guest"
}

// 3. Guard it — the value cannot be reached except through the lock, so the
//    enclosing type needs no @unchecked anywhere.
enum Metrics {
  static let launches = Atomic<Int>(0)
  static let byScreen = Mutex<[String: Int]>([:])

  static func record(_ screen: String) {
    _ = launches.wrappingAdd(1, ordering: .relaxed)
    byScreen.withLock { $0[screen, default: 0] += 1 }
  }
}

final class Report {           // not Sendable: mutable stored properties
  var title = ""
  var rows: [String] = []
}

actor Archive {
  private var stored: [Report] = []
  func store(_ report: Report) { stored.append(report) }
}

// LEGAL — `report` is born here, nothing else can reach it, and the call is its
// last use. The region is disconnected, so it may be sent.
func archiveFresh(_ archive: Archive) async {
  let report = Report()
  report.title = "Weekly"
  report.rows = ["a", "b"]
  await archive.store(report)
}

// REJECTED — the region is consumed by the send; even a read afterwards is a use.
//   error: sending 'report' risks causing data races
//   note: ... between actor-isolated and local nonisolated uses
func archiveThenLog(_ archive: Archive) async {
  let report = Report()
  await archive.store(report)
  // print(report.title)
}

// REJECTED — assigning to `self` merges the report's region with the object's,
// so by the time of the call it is not disconnected any more.
final class Builder {
  var last: Report?
  func build(into archive: Archive) async {
    let report = Report()
    // last = report
    await archive.store(report)
  }
}

// REJECTED — a parameter is task-isolated, never disconnected:
//   note: sending task-isolated 'report' to actor-isolated instance method 'store'
// func forward(_ report: Report, to archive: Archive) async {
//   await archive.store(report)
// }

// ACCEPTED — `sending` pushes the proof obligation onto the caller, who really
// does own the value and really is finished with it.
func forward(_ report: sending Report, to archive: Archive) async {
  await archive.store(report)
}

final class Draft { var body = "" }        // not Sendable

actor Outbox {
  private var queued: [Draft] = []
  func queue(_ d: Draft) { queued.append(d) }
}

// @Sendable constrains CAPTURES, so this closure may not close over a Draft
// at all — no matter how carefully the caller behaves.
func onBackground(_ work: @Sendable @escaping () -> Void) {
  Task.detached { work() }
}

func rejected() {
  let draft = Draft()
  // onBackground { draft.body = "hi" }
  //   error: capture of 'draft' with non-Sendable type 'Draft'
  //          in a '@Sendable' closure
  _ = draft
}

// `sending` says nothing about the type: it transfers one value. The caller
// must own it and stop using it; the callee receives it disconnected.
func hand(_ draft: sending Draft, to outbox: Outbox) async {
  await outbox.queue(draft)
}

// Without `sending` the identical body fails — inside the function the
// parameter is task-isolated, so there is nothing to transfer:
// func hand2(_ draft: Draft, to outbox: Outbox) async {
//   await outbox.queue(draft)          // error: sending 'draft' risks races
// }

// `sending` on a RESULT: the callee promises a freshly disconnected value.
func makeDraft(_ body: String) -> sending Draft {
  let d = Draft()
  d.body = body
  return d
}

// Task.init takes a `sending` closure (SE-0430), not a @Sendable one — which is
// exactly why this captures a non-Sendable Draft and still compiles.
func send(to outbox: Outbox) {
  let draft = makeDraft("hello")
  Task { await outbox.queue(draft) }
}

@MainActor
final class Model {
  let id: Int
  var rows: [String] = []
  init(id: Int) { self.id = id }
}

// error: conformance of 'Model' to protocol 'Equatable' crosses into
//        main actor-isolated code and can cause data races
// note:  main actor-isolated operator function '==' cannot satisfy
//        nonisolated requirement
// extension Model: Equatable {
//   static func == (a: Model, b: Model) -> Bool { a.id == b.id }
// }

// 1. nonisolated witness — honest here, because it only reads `let id`.
extension Model: Equatable {
  nonisolated static func == (a: Model, b: Model) -> Bool { a.id == b.id }
}

// 2. Isolated conformance (SE-0470): the witness MAY read isolated state,
//    and only main-actor code may use the conformance.
@MainActor
final class Row { var text = "" }

extension Row: @MainActor CustomStringConvertible {
  var description: String { "Row(\(text))" }   // reads main-actor state legally
}

// ...but an isolated conformance is not portable:
// func describe<T: CustomStringConvertible & SendableMetatype>(_ t: T.Type) {}
// describe(Row.self)
//   error: main actor-isolated conformance of 'Row' to 'CustomStringConvertible'
//          cannot satisfy conformance requirement for a 'Sendable' type parameter

// 3. An async requirement can be witnessed by an isolated async method: the
//    caller's `await` is the hop the synchronous version could not insert.
protocol Loader { func load() async throws }

extension Model: Loader {
  func load() async throws { rows = ["a", "b"] }
}

// 4. Isolate the protocol itself — every conformer inherits the isolation.
@MainActor protocol Presentable { var title: String { get } }

extension Model: Presentable {
  var title: String { "Model \(id) (\(rows.count))" }
}

// The SDK predates concurrency: no Sendable annotations, and its delegate
// protocol is nonisolated.
@preconcurrency import LegacyPlayer
import Foundation

@MainActor
final class PlayerBox: NSObject {
  private let player = LegacyPlayer()   // without the attribute: non-Sendable type
  private var playCount = 0

  func warm() {
    // Silenced by the IMPORT: the compiler now assumes LegacyPlayer is Sendable.
    // If it is not, this is a genuine data race with no diagnostic at all.
    Task.detached { [player] in player.prewarm() }
  }

  func show(_ error: Error) { print(error) }
}

// error: conformance of 'PlayerBox' to protocol 'LegacyPlayerDelegate' crosses
//        into main actor-isolated code and can cause data races
// extension PlayerBox: LegacyPlayerDelegate {
//   func playerDidFinish() { playCount += 1 }
// }

// @preconcurrency on the CONFORMANCE: the compiler emits a dynamic isolation
// check in the witness thunk (SE-0423). If the SDK ever calls back off the main
// thread this traps — a crash in production instead of a silent race.
extension PlayerBox: @preconcurrency LegacyPlayerDelegate {
  func playerDidFinish() { playCount += 1 }   // main-actor state, checked at runtime
}

// The version that assumes nothing: keep the witness nonisolated and hop
// explicitly. It costs a turn of the run loop and cannot trap.
extension PlayerBox {
  nonisolated func playerDidFail(_ error: Error) {
    Task { @MainActor in self.show(error) }
  }
}

// A global actor is a type that names ONE shared actor instance.
@globalActor
actor StorageActor {
  static let shared = StorageActor()
}

@StorageActor
final class DiskStore {            // every member is isolated to StorageActor.shared
  private var index: [String: URL] = [:]
  func url(for key: String) -> URL? { index[key] }
  nonisolated let name = "disk"    // the seam: readable from any domain
}

// error: global actor 'MainActor' cannot be applied to a declaration
//        already isolated to global actor 'StorageActor'
// @MainActor @StorageActor func flush() { }

@MainActor
final class LibraryModel {
  var rows: [Row] = []

  func reload(store: DiskStore) async {
    rows = []                                  // on the main actor
    let found = await store.url(for: "index")  // SUSPENDS: leaves the main actor
    // Anything queued on the main actor ran here — `rows` may not be [] any more.
    render(found)                              // back, after a real hop
  }

  private func render(_ url: URL?) { }
}

// Queues nested; isolation does not. The only way to be "in both" is in time:
// be isolated to one, and await the other.
@StorageActor
func exportAll(model: LibraryModel) async {
  let count = await model.rows.count   // hop to MainActor and back
  print(count)
}

import Dispatch

// 1. The cheap case: the library only needs serialisation.
actor ImagePipeline {
  private let queue = DispatchSerialQueue(label: "image.pipeline")
  // DispatchSerialQueue already conforms to SerialExecutor.
  nonisolated var unownedExecutor: UnownedSerialExecutor {
    queue.asUnownedSerialExecutor()
  }

  func encode(_ raw: RawFrame) -> Data { legacy_encode(raw) }  // runs on `queue`
  nonisolated let format = "jpeg"   // NOT on the executor: runs on the caller
}

// 2. The library wants one specific THREAD (thread-local context, GL-style API).
// A queue cannot promise that; a dedicated thread can.
final class PinnedExecutor: SerialExecutor {
  private let thread = PinnedThread.start()

  func enqueue(_ job: consuming ExecutorJob) {
    let unowned = UnownedJob(job)                    // hand ownership to the thread
    let me = asUnownedSerialExecutor()
    thread.perform { unowned.runSynchronously(on: me) }   // run it exactly once
  }

  func asUnownedSerialExecutor() -> UnownedSerialExecutor {
    UnownedSerialExecutor(ordinary: self)
  }

  // Without this, assumeIsolated cannot verify a claim about this executor.
  func checkIsolated() {
    precondition(thread.isCurrent, "not on the pinned thread")
  }
}

actor Decoder {
  private let executor = PinnedExecutor()
  nonisolated var unownedExecutor: UnownedSerialExecutor {
    executor.asUnownedSerialExecutor()
  }

  func decode(_ data: Data) -> RawFrame { legacy_decode(data) }
}

import UIKit

@MainActor
final class Player {
  private var progress: Double = 0
  private let bar = UIProgressView()

  // The SDK's protocol requirement is nonisolated, and its docs say
  // "delivered on the main thread".
  nonisolated func vendorDidTick(_ value: Double) {
    // RIGHT: we are already on the main actor, so isolation is lent
    // synchronously — no extra turn of the run loop, no reordering.
    MainActor.assumeIsolated {
      progress = value
      bar.progress = Float(value)
    }
  }

  // WRONG: this one is documented to arrive on the SDK's own queue.
  // assumeIsolated does not move work — the precondition fails and the
  // process traps, in release too.
  nonisolated func vendorDidFinish(_ url: URL) {
    // MainActor.assumeIsolated { progress = 1 }   // crash
    Task { @MainActor in self.progress = 1 }       // asynchronous, but correct
  }
}

// Not a way ONTO the actor: the check asks "am I here?", not "put me here".
func fromAnywhere(_ p: Player) {
  // MainActor.assumeIsolated { p.vendorDidTick(0) }   // traps off the main actor
}

// The instance-actor forms, for asserting without borrowing isolation.
actor Cache {
  func mustBeMine() {
    assertIsolated()          // debug builds
    preconditionIsolated()    // release too
  }
}

@MainActor
final class Profile: Equatable, Hashable {
  let id: UUID                 // Sendable `let`: already readable cross-domain
  var displayName: String      // main-actor isolated

  init(id: UUID, name: String) { self.id = id; displayName = name }

  nonisolated var key: String { id.uuidString }   // reads only immutable storage

  // Protocol witnesses are nonisolated requirements, so the implementations
  // must be too — and may touch nothing isolated.
  nonisolated static func == (a: Profile, b: Profile) -> Bool { a.id == b.id }
  nonisolated func hash(into hasher: inout Hasher) { hasher.combine(id) }

  // TRAP: nothing here runs "in the background". Called from the main actor,
  // this blocks the main thread for the whole loop.
  nonisolated func checksum(_ data: Data) -> Int {
    data.reduce(0) { $0 &+ Int($1) }
  }

  // Inherits the caller's isolation: from the main actor, this IS the main actor.
  nonisolated func summary(_ data: Data) async -> Int { checksum(data) }

  // The one that actually leaves: always the cooperative pool, so Data and Int
  // have to be Sendable.
  @concurrent nonisolated func heavyChecksum(_ data: Data) async -> Int {
    checksum(data)
  }
}

// SE-0434: a Sendable `var` may be nonisolated in a global-actor-isolated struct.
@MainActor
struct Settings {
  nonisolated var launchCount: Int = 0
  var theme: Theme = .light
}

