// ---- Inside AppUI: nothing is annotated, everything is @MainActor ----
final class FeedModel {                      // implicitly @MainActor
  var rows: [Row] = []
  func reload() async throws {               // implicitly @MainActor
    rows = try await decode(Feed.raw())      // the hop is written down below
  }
}

// Leaving the main actor is now the explicit act.
@concurrent
func decode(_ data: Data) async throws -> [Row] {
  try JSONDecoder().decode([Row].self, from: data)
}

// ---- Inside NetworkKit: isolation is spelled out, never inherited ----
public actor TokenStore {                    // callers are not forced onto main
  private var token: String?
  public func current() -> String? { token }
}

// If NetworkKit had defaultIsolation(MainActor), THIS would be @MainActor and
// every consumer would have to hop to the main thread to parse a response.
public struct ResponseParser {
  public func parse(_ data: Data) throws -> [Row] {
    try JSONDecoder().decode([Row].self, from: data)
  }
}

import Foundation

// ---- The boundary: nonisolated, owns nothing mutable, therefore Sendable. ----
final class ScannerBridge: NSObject, VendorScannerDelegate {
  enum Event: Sendable { case found(String), failed(String) }

  let events: AsyncStream<Event>
  private let continuation: AsyncStream<Event>.Continuation

  override init() {
    (events, continuation) = AsyncStream.makeStream(of: Event.self)
    super.init()
  }

  // Called on the SDK's own thread. `yield` is safe from anywhere.
  func scanner(_ s: VendorScanner, didFind code: String) {
    continuation.yield(.found(code))
  }

  func scanner(_ s: VendorScanner, didFailWith error: NSError) {
    continuation.yield(.failed(error.localizedDescription))
    continuation.finish()
  }
}

// ---- Past the boundary everything is isolated and checked again. ----
@MainActor
final class ScannerModel {
  private let bridge = ScannerBridge()
  private var codes: [String] = []      // main-actor state the SDK never sees

  func run() async {
    for await event in bridge.events {  // each iteration resumes on the main actor
      if case .found(let code) = event { codes.append(code) }
    }
  }
}

// WRONG: the model itself is the delegate, so the vendor's thread touches
// main-actor state. @unchecked Sendable makes that compile, not correct.
// extension ScannerModel: VendorScannerDelegate { ... }

// One-shot APIs: resume exactly once, and handle cancellation.
func firstCode(_ scanner: VendorScanner) async -> String? {
  await withTaskCancellationHandler {
    await withCheckedContinuation { c in
      scanner.scanOnce { code in c.resume(returning: code) }
    }
  } onCancel: {
    scanner.stop()
  }
}

import Foundation
import Synchronization

// 1. Pointers are Sendable, so this compiles in Swift 6 mode — and races.
func corrupt(_ buffer: UnsafeMutablePointer<Int>, count: Int) {
  Task.detached { for i in 0..<count { buffer[i] += 1 } }
  Task.detached { for i in 0..<count { buffer[i] += 1 } }
}

// 2. Worse: the pointer is valid only inside the closure.
func normalize(_ samples: inout [Float]) {
  samples.withUnsafeMutableBufferPointer { buf in
    // Task.detached { buf[0] = 1 }   // race AND use-after-free: buf dies at return
    legacy_normalize(buf.baseAddress!, buf.count)   // synchronous: fine
  }
}

// 3. One descriptor, two domains. The file offset lives in the kernel, where
// the checker cannot look: both reads compile, and the bytes interleave.
func split(_ fd: Int32) -> (FileHandle, FileHandle) {
  (FileHandle(fileDescriptor: fd), FileHandle(fileDescriptor: fd))
}

// The fix is what it always was: one owner...
actor LogReader {
  private let handle: FileHandle
  init(fd: Int32) { handle = FileHandle(fileDescriptor: fd) }
  func next(_ n: Int) throws -> Data? { try handle.read(upToCount: n) }
}

// ...or an exclusion the compiler keeps checking for you.
let engine = Mutex<OpaquePointer>(legacy_engine_create())

func render(_ frame: Frame) {
  engine.withLock { legacy_render($0, frame) }   // serialised, and provably so
}

// Compiles clean in Swift 6 mode. TSan reports a race on `pending`.
final class UploadQueue: @unchecked Sendable {   // the check was waived here
  private var pending: [URL] = []
  private let lock = NSLock()

  func add(_ url: URL) {
    lock.lock(); defer { lock.unlock() }
    pending.append(url)
  }

  var count: Int { pending.count }   // ...and the lock was forgotten on THIS path
}

// deinit is nonisolated: it runs wherever the last release happens, which is
// not necessarily the main thread.
@MainActor
final class Row {
  private var timer: Timer?
  deinit { timer?.invalidate() }   // Timer is main-thread-only; this deinit is not
}

// Swift 6.1: make the deinit itself isolated and the hop becomes the runtime's job.
@MainActor
final class FixedRow {
  private var timer: Timer?
  isolated deinit { timer?.invalidate() }
}

// Reproducing it: TSan only reports accesses that actually execute, so the test
// has to create the interleaving itself.
@Test func concurrentAppendsAndReads() async {
  let queue = UploadQueue()
  await withTaskGroup(of: Void.self) { group in
    for i in 0..<200 {
      group.addTask { queue.add(URL(string: "https://example.com/\(i)")!) }
      group.addTask { _ = queue.count }
    }
  }
}
// Run it with the Thread Sanitizer on, then read the "Previous write" stack —
// not the "Write" one. That is the access the fix belongs next to.
